import { Fragment, FormEvent, ReactNode, useCallback, useEffect, useMemo, useRef, useState } from "react";

const apiBase = () => `${window.location.protocol}//${window.location.hostname}:8788`;
type Chore={id:number;title:string;icon:string;points:number;requires_approval:number;assigned_to:string;repeat_mode?:"once"|"weekly";repeat_weekdays?:number[];repeat_target?:number;repeat_completed?:number;repeat_percent?:number;repeat_status?:string;available_today?:boolean};
type History={id:number;title:string;icon:string;points:number;status:"pending"|"awarded"|"rejected";completed_at:string;member:string;cycle_status?:string|null;cycle_completed?:number|null;cycle_required?:number|null;cycle_points?:number|null;reviewable?:number};
type Reward={title:string;emoji:string;target_value:number;unit_label:string;earned:number;remaining:number;percent:number}|null;
type Surprise={id:number;threshold_weeks:number;title:string;emoji:string;active?:number};
type WeeklyAchievement={target_points:number;current_week:string;current_points:number;current_percent:number;total_points?:number;full_tabs?:number;full_weeks?:number;surprises:Surprise[];ready_surprises:Surprise[];next_surprise:Surprise|null;redemptions:Array<{id:number;full_tabs?:number;full_weeks:number;threshold_weeks?:number|null;title:string;created_at:string}>};
type KanbanLane="todo"|"inprogress"|"onhold"|"done";
type KanbanCard={id:number;title:string;description?:string|null;assigned_to:string;lane:KanbanLane;priority:string;due_date?:string|null;created_at:string;updated_at:string};
type Child={id:number;name:string;avatar:string;grade:number|null;chores:Chore[];history:History[];reward:Reward;weekly_achievement?:WeeklyAchievement};
type EventItem={id:string|number;title:string;event_date:string;event_time?:string|null;location?:string|null;member_id?:number|null;member?:string|null};
type Departure={expected_departure:string;aimed_departure?:string|null;destination:string;line:string;platform:string;realtime:boolean};
type Transport={ok?:boolean|null;status:string;stop:string;updated_at?:string|null;stale?:boolean;departures:Departure[]};
type WeatherPeriod={label:string;temperature_min?:number|null;temperature_max?:number|null;precipitation_mm:number;summary:string;symbol:string};
type HealthState="ok"|"degraded"|"stopped";
type AnnualChoreSummary={year:number;children:Array<{id:number;name:string;count:number}>};
type WeekPlanInterpretationItem={category:"homework"|"bring"|"event"|"subject"|"notice"|"general";text:string;source_blocks:string[];confidence:number};
type WeekPlanInterpretation={version:number;week:number;year:number;days:Array<{date:string;weekday:string;items:WeekPlanInterpretationItem[]}>;weekly_tasks?:Array<{text:string;source_blocks:string[]}>;general_info?:Array<{text:string;source_blocks:string[]}>;general_notes?:Array<{text:string;source_blocks:string[]}>};
type WeekPlanDetail={id:number;member_id:number;member:string;week_number:number;year:number;summary?:string|null;full_text:string;interpretation?:WeekPlanInterpretation|null;days:Array<{id:number;week_plan_id:number;day:string;date?:string|null;subject?:string|null;note?:string|null;homework?:string|null;bring?:string|null}>};
type OdaProduct={id:number;name:string;description:string;price:string;unitPrice:string;unitName:string;brand?:string|null;url?:string|null;availability?:{isAvailable:boolean;description:string;code:string}|null};
type OdaCartItem={product:OdaProduct;quantity:number;totalGrossAmount:string};
type OdaCartGroup={id?:number|string;title?:string;groupType?:string;items:OdaCartItem[]};
type OdaCart={groups:OdaCartGroup[];productQuantityCount:number;totalGrossAmount:string;totalBreakdown?:{subtotal:string;productDiscounts:string;couponDiscount:string;surcharge:string;bottleDeposit:string;packaging:string;deliveryFee:string;total:string;surchargeThresholdDescription?:string|null};validationMessages?:string[];deliverySlot?:{id:number;name?:string|null;cutoffTime:string}|null;deliveryAddress?:string|null;url:string};
type OdaStatus={connected:boolean;client_registered:boolean;server_url:string;checkout_url:string;credentials_local:boolean};
type OdaRecipe={id:number;title:string;url?:string|null;imageUrl?:string|null;providerName?:string|null;difficultyString?:string|null;cookingDurationIso8601?:string|null;likeCount?:number|null;liked?:boolean;purchased_before?:boolean;description?:string|null;recipeYield?:string|null;recipeCategory?:string|null;ingredients?:string[];instructions?:string[]};
type DinnerMessage={role:"user"|"assistant";content:string};
type Dashboard={date:string;generated_at:string;annual_chore_summary?:AnnualChoreSummary|null;children:Child[];chores:KanbanCard[];approval_queue:History[];review_queue:History[];events:EventItem[];spond_events:EventItem[];activities:Array<{id:number;name:string;location?:string|null;schedule?:string|null;member_id?:number|null;member?:string|null}>;week_plans:Array<{id:number;member_id:number;member:string;summary:string;week_number?:number;year?:number;fallback?:boolean}>;week_plan_days:Array<{id:number;week_plan_id:number;member_id:number;member:string;day:string;date?:string|null;subject?:string|null;note?:string|null;homework?:string|null;bring?:string|null}>;school_calendar:Array<{id:number;name:string;start_date:string;end_date:string}>;weather:{status:string;updated_at?:string|null;period_date?:string|null;advice?:string;periods?:WeatherPeriod[]};transport:Transport;sources:{email:{latest_processed?:string|null;waiting:number};spond:{checked_at?:string|null;ok?:boolean|null};health:{status:HealthState;ok:boolean;checked_at?:string|null;issues:Array<{service:string;label:string;severity:"warn"|"critical"}>}}};
type Page="family"|"child"|"week-plan"|"parent"|"kanban"|"oda";

const icons=["📖","🧹","🍽️","🧺","🪥","🎒","🗑️","🌱","✨","🎵"];
const dateFormat=new Intl.DateTimeFormat("nb-NO",{weekday:"short",day:"numeric",month:"short"});
const timeFormat=new Intl.DateTimeFormat("nb-NO",{hour:"2-digit",minute:"2-digit"});
const dashboardClockFormat=new Intl.DateTimeFormat("nb-NO",{hour:"2-digit",minute:"2-digit",second:"2-digit",hourCycle:"h23",timeZone:"Europe/Oslo"});
function asDate(value?:string|null){if(!value)return null;const result=new Date(value.length===10?`${value}T12:00:00`:value.replace(" ","T"));return Number.isNaN(result.getTime())?null:result}
function when(value?:string|null){const parsed=asDate(value);return parsed?`${dateFormat.format(parsed)} · ${timeFormat.format(parsed)}`:"Ikke oppdatert"}
function eventTime(item:EventItem){if(item.event_time)return item.event_time.slice(0,5);const parsed=asDate(item.event_date);return parsed&&item.event_date.includes("T")?timeFormat.format(parsed):"Hele dagen"}
function osloHour(value:Date){const part=new Intl.DateTimeFormat("en-GB",{hour:"2-digit",hourCycle:"h23",timeZone:"Europe/Oslo"}).formatToParts(value).find(item=>item.type==="hour");return Number(part?.value||0)}
function greetingForHour(hour:number){if(hour>=5&&hour<11)return"God morgen";if(hour>=11&&hour<14)return"God dag";if(hour>=14&&hour<18)return"God ettermiddag";return"God kveld"}
function recipeDuration(value?:string|null){const match=value?.match(/^PT(?:(\d+)H)?(?:(\d+)M)?$/);if(!match)return"";const hours=Number(match[1]||0);const minutes=Number(match[2]||0);return hours?`${hours} t${minutes?` ${minutes} min`:""}`:`${minutes} min`}
function OdaRecipeImage({recipe}:{recipe:OdaRecipe}){
  if(!recipe.imageUrl)return <div className="oda-recipe-image placeholder" aria-hidden="true">🍽️</div>;
  // The signed Oda URL is already optimized and cannot pass through a local image transformer.
  // eslint-disable-next-line @next/next/no-img-element
  return <img className="oda-recipe-image" src={recipe.imageUrl} alt={recipe.title} loading="lazy" referrerPolicy="no-referrer"/>;
}
function OdaRecipeDetail({recipe,portions,busy,onBack,onAdd}:{recipe:OdaRecipe;portions:number;busy:boolean;onBack:()=>void;onAdd:()=>void}){
  const backButton=useRef<HTMLButtonElement>(null);const onBackRef=useRef(onBack);
  useEffect(()=>{onBackRef.current=onBack},[onBack]);
  useEffect(()=>{backButton.current?.focus();const close=(event:KeyboardEvent)=>{if(event.key==="Escape")onBackRef.current()};window.addEventListener("keydown",close);return()=>window.removeEventListener("keydown",close)},[]);
  const hasRecipe=Boolean(recipe.ingredients?.length||recipe.instructions?.length);
  return <div className="oda-recipe-dialog" role="dialog" aria-modal="true" aria-labelledby="oda-recipe-detail-title"><article className="oda-recipe-detail">
    <button type="button" className="back-button" ref={backButton} onClick={onBack}>← Tilbake til middagsforslag</button>
    <div className="oda-recipe-detail-hero"><OdaRecipeImage recipe={recipe}/><header><p className="eyebrow">Oppskrift fra Oda</p><h2 id="oda-recipe-detail-title">{recipe.title}</h2><p>{[recipe.providerName,recipe.difficultyString,recipeDuration(recipe.cookingDurationIso8601),recipe.recipeYield].filter(Boolean).join(" · ")}</p>{recipe.description&&<p>{recipe.description}</p>}</header></div>
    {hasRecipe?<div className="oda-recipe-detail-body">
      <section><h3>Ingredienser</h3><ul>{recipe.ingredients?.map((ingredient,index)=><li key={`${ingredient}-${index}`}>{ingredient}</li>)}</ul></section>
      <section><h3>Slik gjør du</h3><ol>{recipe.instructions?.map((instruction,index)=><li key={index}>{instruction}</li>)}</ol></section>
    </div>:<p className="oda-recipe-detail-empty">Oda har ikke gjort oppskriftsdetaljene tilgjengelige akkurat nå.</p>}
    <div className="oda-recipe-detail-actions"><button type="button" onClick={onAdd} disabled={busy}>{busy?"Legger til …":`Legg alle ingrediensene i kurven · ${portions} porsjoner`}</button><button type="button" className="back-button" onClick={onBack}>Tilbake</button></div>
  </article></div>;
}
const weekPlanBullet=/^\s*([-–—*•·▪◦‣]|\d+[.)]|[A-Za-zÆØÅæøå][.)])\s+(.+)$/;
function weekPlanHeading(line:string){return line.length<=100&&(/:$/.test(line)||/^(?:mandag|tirsdag|onsdag|torsdag|fredag|lørdag|søndag|ukeplan|uke\s+\d+|lekser|husk|beskjeder|dette skjer|læringsmål)\b/i.test(line)||/^[A-ZÆØÅ0-9][A-ZÆØÅ0-9\s–—-]{3,}$/.test(line))}
function renderWeekPlanText(text:string){
  const lines=text.replace(/\r\n?/g,"\n").split("\n").map(line=>line.trim());
  const blocks:ReactNode[]=[];
  let index=0;
  while(index<lines.length){
    if(!lines[index]){index+=1;continue}
    const bullet=lines[index].match(weekPlanBullet);
    if(bullet){
      const items:string[]=[];const ordered=/^\d/.test(bullet[1]);
      while(index<lines.length){
        const match=lines[index].match(weekPlanBullet);
        if(!match||/^\d/.test(match[1])!==ordered)break;
        items.push(match[2]);index+=1;
      }
      const List=ordered?"ol":"ul";
      blocks.push(<List className="week-plan-list" key={`list-${index}`}>{items.map((item,itemIndex)=><li key={`${index}-${itemIndex}`}>{item}</li>)}</List>);
      continue;
    }
    if(weekPlanHeading(lines[index])){blocks.push(<h3 className="week-plan-heading" key={`heading-${index}`}>{lines[index]}</h3>);index+=1;continue}
    const prose:string[]=[];
    while(index<lines.length&&lines[index]&&!weekPlanBullet.test(lines[index])&&!weekPlanHeading(lines[index])){prose.push(lines[index]);index+=1}
    blocks.push(<p key={`paragraph-${index}`}>{prose.map((line,lineIndex)=><Fragment key={`${index}-${lineIndex}`}>{line}{lineIndex<prose.length-1&&<br/>}</Fragment>)}</p>);
  }
  return <div className="week-plan-rich-text" aria-label="Strukturert ukeplan">{blocks.length?blocks:<p className="empty-text">Ingen plantekst er tilgjengelig.</p>}</div>;
}
const interpretationLabels:Record<WeekPlanInterpretationItem["category"],string>={homework:"Lekse",bring:"Husk",event:"Dette skjer",subject:"Fag",notice:"Beskjed",general:"Info"};
function renderWeekPlanInterpretation(interpretation:WeekPlanInterpretation){
  const days=interpretation.days.filter(day=>day.items.length>0);
  const weeklyTasks=interpretation.weekly_tasks||[];
  const generalInfo=interpretation.general_info||interpretation.general_notes||[];
  return <div className="week-plan-interpretation" aria-label="Tolkede ukeplanpunkter">
    {days.map(day=><section className="week-plan-interpretation-day" key={day.date}>
      <h3>{day.weekday}</h3>
      <ul>{day.items.map((item,index)=><li key={`${day.date}-${index}`}><span className="week-plan-item-category">{interpretationLabels[item.category]}</span>{item.text}</li>)}</ul>
    </section>)}
    {weeklyTasks.length>0&&<section className="week-plan-weekly-tasks"><h3>Dette må gjøres denne uken</h3><ul>{weeklyTasks.map((note,index)=><li key={index}>{note.text}</li>)}</ul></section>}
    {generalInfo.length>0&&<section className="week-plan-general-info"><h3>Generell informasjon</h3><ul>{generalInfo.map((note,index)=><li key={index}>{note.text}</li>)}</ul></section>}
    {days.length===0&&weeklyTasks.length===0&&generalInfo.length===0&&<p className="empty-text">Ingen strukturerte punkter er tilgjengelige.</p>}
  </div>;
}
function completionKey(childId:number,choreId:number){
  const webCrypto=globalThis.crypto;
  if(typeof webCrypto?.randomUUID==="function")return `${childId}-${choreId}-${webCrypto.randomUUID()}`;
  if(typeof webCrypto?.getRandomValues==="function"){const bytes=new Uint32Array(4);webCrypto.getRandomValues(bytes);return `${childId}-${choreId}-${Array.from(bytes,value=>value.toString(36)).join("-")}`}
  return `${childId}-${choreId}-${Date.now().toString(36)}-${Math.random().toString(36).slice(2)}`;
}

export function FamilyConsole(){
  const [data,setData]=useState<Dashboard|null>(null);const [token,setToken]=useState("");const [parentToken,setParentToken]=useState("");
  const sessionToken=useRef("");
  const [page,setPage]=useState<Page>(()=>{if(typeof window==="undefined")return "family";const params=new URLSearchParams(window.location.search);return params.has("weekplan")?"week-plan":params.has("child")?"child":params.has("oda")?"oda":"family"});const [childId,setChildId]=useState<number|null>(()=>typeof window!=="undefined"?Number(new URLSearchParams(window.location.search).get("child"))||null:null);const [weekPlanId,setWeekPlanId]=useState<number|null>(()=>typeof window!=="undefined"?Number(new URLSearchParams(window.location.search).get("weekplan"))||null:null);const [busy,setBusy]=useState<number|string|null>(null);const [notice,setNotice]=useState("");const [error,setError]=useState("");
  const load=useCallback(async()=>{try{const session=await fetch(`${apiBase()}/api/session`,{cache:"no-store"});if(!session.ok)throw new Error("Datatjenesten svarer ikke.");const nextToken=(await session.json()).token;if(sessionToken.current&&sessionToken.current!==nextToken){window.location.reload();return}sessionToken.current=nextToken;setToken(nextToken);const response=await fetch(`${apiBase()}/api/dashboard`,{headers:{"X-FamilyBot-Local-Token":nextToken},cache:"no-store"});if(!response.ok)throw new Error("Familiedata kunne ikke leses.");setData(await response.json());setError("")}catch(cause){setError(cause instanceof Error?cause.message:"Ukjent feil")}},[]);
  useEffect(()=>{const timer=window.setTimeout(()=>{void load()},0);const refresh=window.setInterval(()=>{void load()},30_000);return()=>{window.clearTimeout(timer);window.clearInterval(refresh)}},[load]);
  const child=useMemo(()=>data?.children.find(item=>item.id===childId)||null,[data,childId]);
  async function mutate(path:string,method:string,body?:unknown,parent=false){const response=await fetch(`${apiBase()}${path}`,{method,headers:{"Content-Type":"application/json","X-FamilyBot-Local-Token":token,...(parent?{"X-FamilyBot-Parent-Token":parentToken}:{})},body:body?JSON.stringify(body):undefined});const result=await response.json();if(!response.ok)throw new Error(result.error||"Endringen kunne ikke lagres.");return result}
  function openFamily(){history.replaceState(null,"","/");setPage("family");setChildId(null);setWeekPlanId(null);setNotice("")}
  function openChild(id:number){history.replaceState(null,"",`/?child=${id}`);setChildId(id);setWeekPlanId(null);setPage("child");setNotice("");window.scrollTo(0,0)}
  function openWeekPlan(id:number,planId:number){history.replaceState(null,"",`/?child=${id}&weekplan=${planId}`);setChildId(id);setWeekPlanId(planId);setPage("week-plan");setNotice("");window.scrollTo(0,0)}
  function backToChild(){if(childId===null)return;history.replaceState(null,"",`/?child=${childId}`);setWeekPlanId(null);setPage("child");window.scrollTo(0,0)}
  async function complete(chore:Chore){if(!child||busy)return;setBusy(chore.id);try{const result=await mutate(`/api/chores/${chore.id}/complete`,"POST",{member_id:child.id,idempotency_key:completionKey(child.id,chore.id)});const completion=result.completion;setNotice(completion.repeat_target&&completion.repeat_target>1?(completion.repeat_status==="pending"?`Alle repetisjoner er gjort. ${chore.points} poeng venter på godkjenning. ✅`:completion.repeat_status==="awarded"?`Ferdig! ${chore.points} poeng er lagt til ⭐`:`Registrert: ${completion.repeat_completed}/${completion.repeat_target} · +${chore.points} poeng ✅`):`Ferdig! ${chore.points} poeng er lagt til ⭐`);await load()}catch(cause){setError(cause instanceof Error?cause.message:"Kunne ikke registrere.")}finally{setBusy(null)}}
  async function unlock(event:FormEvent<HTMLFormElement>){event.preventDefault();setBusy("pin");try{const form=new FormData(event.currentTarget);const result=await mutate("/api/parent/session","POST",{pin:form.get("pin")});setParentToken(result.parent_token);setNotice("Foreldremodus er låst opp.")}catch(cause){setError(cause instanceof Error?cause.message:"Feil kode.")}finally{setBusy(null)}}
  async function addChore(event:FormEvent<HTMLFormElement>){event.preventDefault();setBusy("add");const element=event.currentTarget;const form=new FormData(element);try{await mutate("/api/chores","POST",{title:form.get("title"),assigned_to:form.get("assigned_to"),icon:form.get("icon"),points:Number(form.get("points")),requires_approval:form.get("requires_approval")==="on",repeat_mode:form.get("repeat_mode")==="weekly"?"weekly":"once",repeat_weekdays:form.getAll("repeat_weekdays")},true);element.reset();setNotice("Oppdraget er klart på barnets side.");await load()}catch(cause){setError(cause instanceof Error?cause.message:"Kunne ikke legge til.")}finally{setBusy(null)}}
  async function addKanban(event:FormEvent<HTMLFormElement>){event.preventDefault();setBusy("kanban-add");const element=event.currentTarget;const form=new FormData(element);try{await mutate("/api/kanban","POST",{title:form.get("title"),description:form.get("description"),assigned_to:form.get("assigned_to")||"both",priority:form.get("priority"),due_date:form.get("due_date")||null},true);element.reset();setNotice("Oppgaven er lagt til i Kanban.");await load()}catch(cause){setError(cause instanceof Error?cause.message:"Kunne ikke legge til oppgaven.")}finally{setBusy(null)}}
  async function moveKanban(id:number,lane:KanbanLane){if(busy)return;setBusy(`kanban-move-${id}`);try{await mutate(`/api/kanban/${id}`,"PATCH",{lane},true);setNotice("Kanban-status er oppdatert.");await load()}catch(cause){setError(cause instanceof Error?cause.message:"Kunne ikke flytte oppgaven.")}finally{setBusy(null)}}
  async function archiveKanban(id:number){if(busy||!window.confirm("Fjerne denne oppgaven fra Kanban? Den beholdes i databasen."))return;setBusy(`kanban-delete-${id}`);try{await mutate(`/api/kanban/${id}`,"DELETE",undefined,true);setNotice("Oppgaven er fjernet fra Kanban.");await load()}catch(cause){setError(cause instanceof Error?cause.message:"Kunne ikke fjerne oppgaven.")}finally{setBusy(null)}}
  async function decide(id:number,decision:"awarded"|"rejected"){setBusy(`approval-${id}`);try{await mutate(`/api/completions/${id}`,"PATCH",{decision},true);setNotice(decision==="awarded"?"Poengene er godkjent.":"Oppdraget er sendt tilbake.");await load()}catch(cause){setError(cause instanceof Error?cause.message:"Kunne ikke lagre.")}finally{setBusy(null)}}
  async function archive(id:number){setBusy(`archive-${id}`);try{await mutate(`/api/chores/${id}`,"DELETE",undefined,true);setNotice("Oppdraget er fjernet.");await load()}catch(cause){setError(cause instanceof Error?cause.message:"Kunne ikke fjerne.")}finally{setBusy(null)}}
  async function reward(event:FormEvent<HTMLFormElement>){event.preventDefault();setBusy("reward");const form=new FormData(event.currentTarget);try{await mutate("/api/rewards","POST",{member_id:Number(form.get("member_id")),title:form.get("title"),emoji:form.get("emoji"),goal_type:"points",target_value:Number(form.get("target_value")),unit_label:"poeng"},true);setNotice("Nytt belønningsmål er satt.");await load()}catch(cause){setError(cause instanceof Error?cause.message:"Kunne ikke lagre.")}finally{setBusy(null)}}
  async function saveWeeklySurprise(event:FormEvent<HTMLFormElement>){event.preventDefault();setBusy("weekly-surprise");const form=new FormData(event.currentTarget);try{await mutate(`/api/children/${Number(form.get("member_id"))}/weekly-achievement/surprises`,"POST",{threshold_weeks:Number(form.get("threshold_weeks")),title:form.get("title"),emoji:form.get("emoji")},true);event.currentTarget.reset();setNotice("Overraskelsen er lagret.");await load()}catch(cause){setError(cause instanceof Error?cause.message:"Kunne ikke lagre overraskelsen.")}finally{setBusy(null)}}
  async function deleteWeeklySurprise(memberId:number,threshold:number){if(busy)return;setBusy(`weekly-delete-${threshold}`);try{await mutate(`/api/children/${memberId}/weekly-achievement/surprises/${threshold}`,"DELETE",undefined,true);setNotice("Overraskelsen er fjernet.");await load()}catch(cause){setError(cause instanceof Error?cause.message:"Kunne ikke fjerne overraskelsen.")}finally{setBusy(null)}}
  async function resetWeeklyAchievement(memberId:number,threshold?:number){if(busy||!window.confirm("Er overraskelsen tatt ut? Dette starter telleren på nytt, men beholder historikken."))return;setBusy(`weekly-reset-${memberId}`);try{await mutate(`/api/children/${memberId}/weekly-achievement/reset`,"POST",{threshold_weeks:threshold,idempotency_key:`weekly-reset-${memberId}-${Date.now()}-${globalThis.crypto?.randomUUID?.()||"key"}`},true);setNotice("Fullførte blokker er nullstilt.");await load()}catch(cause){setError(cause instanceof Error?cause.message:"Kunne ikke nullstille telleren.")}finally{setBusy(null)}}
  async function resetChild(memberId:number,scope:"chores"|"points"|"both"){if(busy||!window.confirm("Nullstill dette barnets oppsett? Historikken beholdes, men aktiv fremgang starter på nytt."))return;setBusy(`reset-${memberId}-${scope}`);try{await mutate(`/api/children/${memberId}/reset`,"POST",{scope,idempotency_key:`reset-${memberId}-${scope}-${globalThis.crypto?.randomUUID?.()||Date.now()}`},true);setNotice("Barnets oppsett er nullstilt.");await load()}catch(cause){setError(cause instanceof Error?cause.message:"Kunne ikke nullstille.")}finally{setBusy(null)}}

  if(!data)return <main className="loading"><div className="spinner"/><h1>Familieportalen våkner …</h1>{error&&<p className="error-text">{error}</p>}<button onClick={()=>void load()}>Prøv igjen</button></main>;
  return <main className={`app page-${page}`}>
    <header className="topbar"><button className="brand" onClick={openFamily}><span>F</span><strong>Familieportalen</strong></button><nav aria-label="Hovedmeny"><button className={page==="family"?"active":""} onClick={openFamily}>I dag</button>{data.children.map(item=><button key={item.id} className={childId===item.id?"active":""} onClick={()=>openChild(item.id)}>{item.avatar} {item.name}</button>)}<button className={page==="parent"?"active":""} onClick={()=>{history.replaceState(null,"","/");setPage("parent");setChildId(null)}}>Foreldre</button><button className={page==="kanban"?"active":""} onClick={()=>{history.replaceState(null,"","/");setPage("kanban");setChildId(null)}}>Kanban</button><button className={page==="oda"?"active":""} onClick={()=>{history.replaceState(null,"","/?oda=1");setPage("oda");setChildId(null)}}>Oda</button></nav></header>
    {error&&<div className="toast error" role="alert">{error}<button onClick={()=>setError("")}>×</button></div>}{notice&&<div className="toast success" role="status">{notice}<button onClick={()=>setNotice("")}>×</button></div>}
    {page==="family"&&<FamilyHome data={data} openChild={openChild}/>}
    {page==="child"&&child&&<ChildPage child={child} data={data} busy={busy} complete={complete} openWeekPlan={openWeekPlan}/>}
    {page==="week-plan"&&child&&weekPlanId&&<WeekPlanDetailPage child={child} planId={weekPlanId} token={token} onBack={backToChild}/>}
    {page==="parent"&&<ParentPage data={data} unlocked={Boolean(parentToken)} busy={busy} unlock={unlock} addChore={addChore} decide={decide} archive={archive} reward={reward} saveWeeklySurprise={saveWeeklySurprise} deleteWeeklySurprise={deleteWeeklySurprise} resetWeeklyAchievement={resetWeeklyAchievement} resetChild={resetChild}/>}
    {page==="kanban"&&<KanbanPage data={data} unlocked={Boolean(parentToken)} busy={busy} unlock={unlock} addKanban={addKanban} moveKanban={moveKanban} archiveKanban={archiveKanban}/>}
    {page==="oda"&&<OdaPage token={token}/>}
  </main>
}

function OdaPage({token}:{token:string}){
  const [status,setStatus]=useState<OdaStatus|null>(null);const [cart,setCart]=useState<OdaCart|null>(null);const [products,setProducts]=useState<OdaProduct[]>([]);const [suggestions,setSuggestions]=useState<OdaProduct[]>([]);const [searchLabel,setSearchLabel]=useState("");const [odaBusy,setOdaBusy]=useState("");const [odaError,setOdaError]=useState("");const [odaNotice,setOdaNotice]=useState("");
  const [dinnerPrompt,setDinnerPrompt]=useState("");const [dinnerPortions,setDinnerPortions]=useState(4);const [dinnerMessages,setDinnerMessages]=useState<DinnerMessage[]>([{role:"assistant",content:"Hva har dere lyst på? Jeg kan foreslå Oda-oppskrifter ut fra ønsket deres og det dere har likt eller kjøpt før."}]);const [dinnerRecipes,setDinnerRecipes]=useState<OdaRecipe[]>([]);const [selectedRecipe,setSelectedRecipe]=useState<OdaRecipe|null>(null);
  const request=useCallback(async(path:string,options:RequestInit={})=>{const response=await fetch(`${apiBase()}${path}`,{...options,headers:{"Content-Type":"application/json","X-FamilyBot-Local-Token":token,...(options.headers||{})},cache:"no-store"});const result=await response.json();if(!response.ok)throw new Error(result.error||"Oda svarer ikke akkurat nå.");return result},[token]);
  const loadStatus=useCallback(async()=>{try{const next=await request("/api/oda/status");setStatus(next);setOdaError("")}catch(cause){setOdaError(cause instanceof Error?cause.message:"Kunne ikke lese Oda-status.")}},[request]);
  const loadCart=useCallback(async()=>{try{const result=await request("/api/oda/cart");setCart(result.cart)}catch(cause){setOdaError(cause instanceof Error?cause.message:"Kunne ikke hente handlekurven.")}},[request]);
  const loadSuggestions=useCallback(async()=>{try{const result=await request("/api/oda/suggestions?kind=likely");setSuggestions(result.suggestions?.result||[])}catch(cause){setOdaError(cause instanceof Error?cause.message:"Kunne ikke hente forslag.")}},[request]);
  useEffect(()=>{const timer=window.setTimeout(()=>void loadStatus(),0);return()=>window.clearTimeout(timer)},[loadStatus]);
  useEffect(()=>{if(!status?.connected)return;const timer=window.setTimeout(()=>{void loadCart();void loadSuggestions()},0);return()=>window.clearTimeout(timer)},[status?.connected,loadCart,loadSuggestions]);
  useEffect(()=>{const params=new URLSearchParams(window.location.search);if(params.get("oda_connected")!=="1")return;params.delete("oda_connected");history.replaceState(null,"",`/?${params.toString()||"oda=1"}`);const timer=window.setTimeout(()=>setOdaNotice("Oda-kontoen er koblet til."),0);return()=>window.clearTimeout(timer)},[]);
  async function connect(){setOdaBusy("connect");setOdaError("");try{const result=await request("/api/oda/connect",{method:"POST",body:"{}"});if(typeof result.authorization_url!=="string"||!result.authorization_url.startsWith("https://"))throw new Error("Oda returnerte ingen gyldig innloggingsadresse.");window.location.assign(result.authorization_url)}catch(cause){setOdaError(cause instanceof Error?cause.message:"Kunne ikke starte Oda-tilkoblingen.")}finally{setOdaBusy("")}}
  async function search(event:FormEvent<HTMLFormElement>){event.preventDefault();const form=new FormData(event.currentTarget);const query=String(form.get("query")||"").trim();if(!query)return;setOdaBusy("search");setOdaError("");try{const result=await request("/api/oda/search",{method:"POST",body:JSON.stringify({query})});setProducts(result.search?.result?.[0]?.products||[]);setSearchLabel(query)}catch(cause){setOdaError(cause instanceof Error?cause.message:"Søket mislyktes.")}finally{setOdaBusy("")}}
  async function askDinner(event:FormEvent<HTMLFormElement>){event.preventDefault();const question=dinnerPrompt.trim();if(!question||odaBusy==="dinner")return;const history=dinnerMessages.slice(-6);setDinnerMessages(current=>[...current,{role:"user",content:question}]);setDinnerPrompt("");setDinnerRecipes([]);setSelectedRecipe(null);setOdaBusy("dinner");setOdaError("");try{const result=await request("/api/oda/dinner",{method:"POST",body:JSON.stringify({question,portions:dinnerPortions,history})});setDinnerMessages(current=>[...current,{role:"assistant",content:result.answer||"Her er noen middagsforslag fra Oda."}]);setDinnerRecipes(result.recipes||[])}catch(cause){setOdaError(cause instanceof Error?cause.message:"Kunne ikke finne middagsforslag.");setDinnerMessages(current=>[...current,{role:"assistant",content:"Jeg fikk ikke hentet forslag akkurat nå. Prøv igjen om litt."}])}finally{setOdaBusy("")}}
  async function addRecipe(recipe:OdaRecipe){setOdaBusy(`recipe-${recipe.id}`);setOdaError("");try{const result=await request(`/api/oda/recipes/${recipe.id}/cart`,{method:"POST",body:JSON.stringify({portions:dinnerPortions})});setCart(result.cart);setOdaNotice(`Alle tilgjengelige ingredienser til ${recipe.title} er lagt i handlekurven for ${dinnerPortions} porsjoner.`)}catch(cause){setOdaError(cause instanceof Error?cause.message:"Kunne ikke legge oppskriften i handlekurven.")}finally{setOdaBusy("")}}
  async function changeProduct(productId:number,quantity:number){setOdaBusy(`product-${productId}`);setOdaError("");try{const result=await request("/api/oda/cart",{method:"POST",body:JSON.stringify({product_id:productId,quantity})});setCart(result.cart);setOdaNotice(quantity>0?"Varen er lagt i handlekurven.":"Handlekurven er oppdatert.")}catch(cause){setOdaError(cause instanceof Error?cause.message:"Kunne ikke oppdatere handlekurven.")}finally{setOdaBusy("")}}
  async function clearCart(){if(!window.confirm("Tømme hele Oda-handlekurven?"))return;setOdaBusy("clear");try{const result=await request("/api/oda/cart",{method:"DELETE"});setCart(result.cart);setOdaNotice("Handlekurven er tømt.")}catch(cause){setOdaError(cause instanceof Error?cause.message:"Kunne ikke tømme handlekurven.")}finally{setOdaBusy("")}}
  async function disconnect(){if(!window.confirm("Koble Oda-kontoen fra Familieportalen?"))return;setOdaBusy("disconnect");try{await request("/api/oda/connection",{method:"DELETE"});setStatus(current=>current?{...current,connected:false}:null);setCart(null);setProducts([]);setSuggestions([]);setOdaNotice("Oda er koblet fra.")}catch(cause){setOdaError(cause instanceof Error?cause.message:"Kunne ikke koble fra Oda.")}finally{setOdaBusy("")}}
  if(!status)return <section className="oda-shell"><div className="loading-inline"><div className="spinner"/><p>Kontakter Oda …</p>{odaError&&<p className="oda-error" role="alert">{odaError}</p>}</div></section>;
  if(!status.connected)return <section className="oda-shell"><div className="oda-heading"><div><p className="eyebrow">Dagligvarer</p><h1>Oda</h1><p>Koble den vanlige Oda-kontoen til Familieportalen én gang.</p></div></div><div className="oda-connect-card"><span>🛒</span><div><h2>Koble til Oda</h2><p>Innloggingen åpnes i det samme vinduet, slik at den også virker i kioskmodus. Etter godkjenning sendes du automatisk tilbake hit.</p><p>Familieportalen lagrer OAuth-tilgangen lokalt på Mac-en, aldri i Git. Vi kan søke, foreslå varer og fylle kurven, mens bestilling og betaling alltid gjøres hos Oda.</p></div><button className="primary" type="button" disabled={odaBusy==="connect"} onClick={()=>void connect()}>{odaBusy==="connect"?"Åpner Oda …":"Logg inn hos Oda"}</button>{odaError&&<p className="oda-error" role="alert">{odaError}</p>}</div></section>;
  const cartLines=(cart?.groups||[]).flatMap(group=>group.items.map(item=>({...item,groupTitle:group.title})));
  const productCard=(product:OdaProduct,source:string)=><article className="oda-product" key={product.id}><div><small>{product.brand||source}</small><h3>{product.name}</h3><p>{product.description}</p><span>{product.unitPrice} / {product.unitName}</span></div><div><strong>{product.price}</strong><button type="button" disabled={odaBusy===`product-${product.id}`||product.availability?.isAvailable===false} onClick={()=>void changeProduct(product.id,1)}>{product.availability?.isAvailable===false?"Ikke tilgjengelig":"+ Legg til"}</button></div></article>;
  const quickDinners=["Rask og barnevennlig","Vegetarisk i dag","Noe nytt basert på det vi liker"];
  return <><section className="oda-shell"><div className="oda-heading"><div><p className="eyebrow">Dagligvarer</p><h1>Oda</h1><p>Søk, finn det dere pleier å kjøpe og gjør kurven klar. Betaling skjer hos Oda.</p></div><button type="button" className="oda-disconnect" disabled={odaBusy==="disconnect"} onClick={()=>void disconnect()}>Koble fra</button></div>
    <div className="oda-safety" role="note"><strong>Du beholder kontrollen</strong><span>Familieportalen kan endre handlekurven etter et trykk. Den kan ikke betale eller fullføre bestillingen.</span></div>
    {odaError&&<p className="oda-error" role="alert">{odaError}</p>}{odaNotice&&<p className="oda-notice" role="status">{odaNotice}<button type="button" onClick={()=>setOdaNotice("")}>×</button></p>}
    <section className="oda-dinner" aria-labelledby="oda-dinner-title"><header><div><p className="eyebrow">Middagsassistent</p><h2 id="oda-dinner-title">Hva skal vi ha til middag? <span aria-hidden="true">❤️</span></h2><p>Fortell hva dere har lyst på. Forslagene kan ta hensyn til Oda-oppskrifter dere har likt eller kjøpt før.</p></div><label htmlFor="oda-portions">Porsjoner<input id="oda-portions" type="number" min={1} max={12} value={dinnerPortions} onChange={event=>setDinnerPortions(Math.max(1,Math.min(12,Number(event.target.value)||1)))}/></label></header>
      <div className="oda-dinner-chat" aria-live="polite">{dinnerMessages.slice(-6).map((message,index)=><div className={`oda-dinner-message ${message.role}`} key={`${message.role}-${index}`}><span>{message.role==="assistant"?"🍽️":"Dere"}</span><p>{message.content}</p></div>)}{odaBusy==="dinner"&&<div className="oda-dinner-message assistant"><span>🍽️</span><p>Ser gjennom oppskrifter hos Oda …</p></div>}</div>
      <div className="oda-dinner-quick" aria-label="Raske middagsønsker">{quickDinners.map(prompt=><button type="button" key={prompt} onClick={()=>setDinnerPrompt(prompt)}>{prompt}</button>)}</div>
      <form className="oda-dinner-form" onSubmit={askDinner}><label htmlFor="oda-dinner-question">Middagsønske<textarea id="oda-dinner-question" minLength={2} maxLength={800} required value={dinnerPrompt} onChange={event=>setDinnerPrompt(event.target.value)} placeholder="For eksempel: Tre raske middager med kylling, lite sterk mat og maks 30 minutter"/></label><button className="primary" disabled={odaBusy==="dinner"}>{odaBusy==="dinner"?"Finner middager …":"Finn middagsforslag"}</button></form>
      {dinnerRecipes.length>0&&<div className="oda-recipe-grid">{dinnerRecipes.map(recipe=><article className="oda-recipe" key={recipe.id}><button type="button" className="oda-recipe-open-image" aria-label={`Se oppskriften ${recipe.title}`} onClick={()=>setSelectedRecipe(recipe)}><OdaRecipeImage recipe={recipe}/></button><div className="oda-recipe-content"><div className="oda-recipe-flags">{recipe.liked&&<span>Likt hos Oda</span>}{recipe.purchased_before&&<span>Kjøpt før</span>}</div><div><small>{[recipe.providerName,recipe.difficultyString,recipeDuration(recipe.cookingDurationIso8601)].filter(Boolean).join(" · ")}</small><h3><button type="button" className="oda-recipe-open-title" onClick={()=>setSelectedRecipe(recipe)}>{recipe.title} →</button></h3></div><button type="button" disabled={odaBusy===`recipe-${recipe.id}`} onClick={()=>void addRecipe(recipe)}>{odaBusy===`recipe-${recipe.id}`?"Legger til …":`Legg alle ingrediensene i kurven · ${dinnerPortions} porsjoner`}</button></div></article>)}</div>}
      <small className="oda-dinner-boundary">Assistenten planlegger bare oppskriftssøk. Ingredienser legges først i kurven når du trykker på knappen.</small>
    </section>
    <div className="oda-layout"><div className="oda-shop"><form className="oda-search" onSubmit={search}><label htmlFor="oda-query">Hva trenger dere?<input id="oda-query" name="query" minLength={2} maxLength={120} required placeholder="Melk, brød, taco …"/></label><button className="primary" disabled={odaBusy==="search"}>{odaBusy==="search"?"Søker …":"Søk hos Oda"}</button></form>
      {products.length>0&&<section className="oda-results"><div className="oda-section-title"><h2>Resultater for «{searchLabel}»</h2><span>{products.length} varer</span></div><div className="oda-products">{products.map(product=>productCard(product,"Søkeresultat"))}</div></section>}
      <section className="oda-results"><div className="oda-section-title"><h2>Dette kjøper dere ofte</h2><button type="button" onClick={()=>void loadSuggestions()}>Oppdater</button></div>{suggestions.length?<div className="oda-products">{suggestions.slice(0,8).map(product=>productCard(product,"Forslag fra Oda"))}</div>:<p className="empty-text">Ingen personlige forslag tilgjengelig akkurat nå.</p>}</section>
    </div><aside className="oda-cart"><div className="oda-cart-heading"><div><p className="eyebrow">Handlekurv</p><h2>{cart?.productQuantityCount||0} varer</h2></div><strong>{cart?.totalGrossAmount||"0 kr"}</strong></div>{cart?.deliverySlot&&<div className="oda-delivery"><strong>{cart.deliverySlot.name||"Levering valgt"}</strong><span>{cart.deliveryAddress}</span></div>}<div className="oda-cart-lines">{cartLines.map((item,index)=><div key={`${item.product.id}-${index}`}><div><strong>{item.quantity} × {item.product.name}</strong>{item.groupTitle&&<small>{item.groupTitle}</small>}<span>{item.totalGrossAmount}</span></div><button type="button" aria-label={`Fjern én ${item.product.name}`} disabled={odaBusy===`product-${item.product.id}`} onClick={()=>void changeProduct(item.product.id,-1)}>−</button></div>)}{cartLines.length===0&&<p className="empty-text">Handlekurven er tom.</p>}</div>{cart?.validationMessages?.map(message=><p className="oda-cart-warning" key={message}>{message}</p>)}{cart?.totalBreakdown?.surchargeThresholdDescription&&<p className="oda-cart-tip">{cart.totalBreakdown.surchargeThresholdDescription}</p>}<a className="oda-checkout" href={cart?.url||"https://oda.com/"} target="_blank" rel="noreferrer">Se gjennom og betal hos Oda ↗</a>{cartLines.length>0&&<button type="button" className="oda-clear" disabled={odaBusy==="clear"} onClick={()=>void clearCart()}>Tøm handlekurven</button>}<small>Utsjekk og betaling er ikke tilgjengelig gjennom MCP.</small></aside></div>
  </section>{selectedRecipe&&<OdaRecipeDetail recipe={selectedRecipe} portions={dinnerPortions} busy={odaBusy===`recipe-${selectedRecipe.id}`} onBack={()=>setSelectedRecipe(null)} onAdd={()=>void addRecipe(selectedRecipe)}/>}</>
}

function JanuaryChoreSummary({summary,onClose}:{summary:AnnualChoreSummary;onClose:()=>void}){
  return <div className="january-splash" role="dialog" aria-modal="true" aria-labelledby="january-summary-title"><div className="january-splash-card"><p className="eyebrow">Et lite tilbakeblikk</p><h2 id="january-summary-title">Dette fikk dere til i {summary.year}</h2><p>Her er antall fullførte oppgaver for hvert barn. Nye oppgaver er klare for et nytt år.</p><div className="january-summary-list">{summary.children.map(child=><div key={child.id}><strong>{child.name}</strong><span>{child.count} {child.count===1?"oppgave":"oppgaver"}</span></div>)}</div><button className="primary" type="button" onClick={onClose}>Til oversikten</button></div></div>;
}

function FamilyHome({data,openChild}:{data:Dashboard;openChild:(id:number)=>void}){
  const [clock,setClock]=useState(()=>{const now=Date.now();return{clientNow:now,syncClientNow:now}});
  const [summaryDismissed,setSummaryDismissed]=useState(false);
  const generatedTime=useMemo(()=>asDate(data.generated_at)?.getTime()??null,[data.generated_at]);
  const syncedClock=useMemo(()=>new Date(generatedTime?generatedTime+(clock.clientNow-clock.syncClientNow):clock.clientNow),[clock,generatedTime]);
  const dashboardClock=dashboardClockFormat.format(syncedClock);
  const summaryYear=data.annual_chore_summary?.year;
  const showJanuarySummary=summaryYear!==undefined&&!summaryDismissed&&typeof window!=="undefined"&&window.sessionStorage.getItem(`familybot-january-summary-${summaryYear}`)!=="seen";
  function closeJanuarySummary(){
    if(summaryYear!==undefined)window.sessionStorage.setItem(`familybot-january-summary-${summaryYear}`,"seen");
    setSummaryDismissed(true);
  }
  useEffect(()=>{const sync=()=>{const now=Date.now();setClock({clientNow:now,syncClientNow:now})};const initial=window.setTimeout(sync,0);const timer=window.setInterval(()=>setClock(current=>({...current,clientNow:Date.now()})),1_000);return()=>{window.clearTimeout(initial);window.clearInterval(timer)}},[data.generated_at]);
  const upcoming=upcomingEventsFor(data);const nextSchool=data.school_calendar.find(item=>item.end_date>=data.date);
  return <>{showJanuarySummary&&data.annual_chore_summary&&<JanuaryChoreSummary summary={data.annual_chore_summary} onClose={closeJanuarySummary}/>}
    <section className="family-hero"><div><p className="eyebrow">Familiens oversikt</p><h1>{greetingForHour(osloHour(syncedClock))}.</h1><p>{new Intl.DateTimeFormat("nb-NO",{weekday:"long",day:"numeric",month:"long"}).format(asDate(data.date)!)}</p></div><div className="hero-clock" aria-label={`Klokken er nå ${dashboardClock}`}><span>Klokken er nå:</span><strong>{dashboardClock}</strong><small>Synket fra FamilyBot</small></div></section>
    <section className="overview-grid" aria-label="Dagens viktigste informasjon">
      <article className="overview-card important"><header><span>📅</span><div><p className="eyebrow">Neste 5 dager</p><h2>Viktigst nå</h2></div></header><div className="timeline">{upcoming.map(item=><div key={`${item.id}-${item.title}`}><time>{eventLabel(item,data.date)}</time><div><strong>{item.title}</strong><small>{item.member||"Familien"}{item.location?` · ${item.location}`:""}</small></div></div>)}{upcoming.length===0&&<p className="empty-text">Ingen særskilte avtaler de neste fem dagene.</p>}</div>{nextSchool&&<div className="info-strip"><strong>{nextSchool.name}</strong><span>{dateFormat.format(asDate(nextSchool.start_date)!)}</span></div>}</article>
      <article className="overview-card weather-card"><header><span>🌦️</span><div><p className="eyebrow">Ute</p><h2>Vær</h2></div></header><div className="big-status">{data.weather.status}</div><WeatherForecast periods={data.weather.periods} periodDate={data.weather.period_date} today={data.date}/><div className="weather-advice"><strong>{data.weather.period_date&&data.weather.period_date!==data.date?"Råd for neste dag":"Råd for i dag"}</strong><p>{data.weather.advice||"Sjekk værvarselet før dere går."}</p></div><small>Værkilde {when(data.weather.updated_at)}</small></article>
      <article className="overview-card transport-card"><header><span>🚇</span><div><p className="eyebrow">På vei</p><h2>T-bane</h2></div></header><TransportCountdown transport={data.transport}/></article>
      <article className="overview-card"><header><span>🎒</span><div><p className="eyebrow">Skole og fritid</p><h2>Aktiviteter</h2></div></header><div className="compact-list">{data.activities.slice(0,5).map(item=><div key={item.id}><span>{item.member?.slice(0,1)||"F"}</span><div><strong>{item.name}</strong><small>{item.member}{item.schedule?` · ${item.schedule}`:" · Tid kommer"}</small></div></div>)}{data.activities.length===0&&<p className="empty-text">Ingen faste aktiviteter registrert.</p>}</div></article>
    </section>
    <section className="family-members"><div className="section-heading"><div><p className="eyebrow">Barnas sider</p><h2>Oppdrag og belønning</h2></div><p>Ett trykk til egen side</p></div><div className="account-grid">{data.children.map(child=>{const achievement=child.weekly_achievement;const fullTabs=achievement?.full_tabs??achievement?.full_weeks??0;const blockPoints=achievement?.current_points??0;const blockTarget=achievement?.target_points??30;const blockPercent=achievement?.current_percent??0;return <button key={child.id} className="child-account" onClick={()=>openChild(child.id)}><span className="account-avatar">{child.avatar}</span><div><strong>{child.name}</strong><small>{child.chores.length?`${child.chores.length} oppdrag igjen`:"Ingen oppdrag ennå"}</small></div><div className="mini-balance"><strong>{blockPoints} / {blockTarget}</strong><span>{fullTabs} fulle blokker</span><div><i style={{width:`${blockPercent}%`}}/></div></div><b>→</b></button>})}</div></section>
  </>
}

function WeatherForecast({periods,periodDate,today}:{periods?:WeatherPeriod[];periodDate?:string|null;today:string}){
  if(!periods?.length)return <p className="weather-unavailable">Detaljert varsel kommer når neste oppdatering er hentet.</p>;
  return <div className="weather-forecast" aria-label="Detaljert værvarsel"><p className="weather-forecast-title">{periodDate&&periodDate!==today?"Neste dag":"I dag"}</p><div className="weather-periods">{periods.map(period=><div className="weather-period" key={period.label}><strong>{period.label}</strong><span>{period.temperature_min===null||period.temperature_min===undefined?"—":`${period.temperature_min}–${period.temperature_max} °C`}</span><small>{period.summary}</small><small>{period.precipitation_mm} mm</small></div>)}</div></div>
}

function TransportCountdown({transport}:{transport:Transport}){
  const [now,setNow]=useState(()=>Date.now());
  useEffect(()=>{const timer=window.setInterval(()=>setNow(Date.now()),1_000);return()=>window.clearInterval(timer)},[]);
  const upcoming=transport.departures.filter(item=>{const departure=asDate(item.expected_departure);return departure&&departure.getTime()>now-30_000});
  const next=upcoming[0];
  const seconds=next?Math.max(0,Math.ceil((asDate(next.expected_departure)!.getTime()-now)/1_000)):null;
  const countdown=seconds===null?null:seconds<60?`${seconds} sek`:seconds<3_600?`${Math.floor(seconds/60)} min ${String(seconds%60).padStart(2,"0")} sek`:`${Math.floor(seconds/3_600)} t ${Math.floor(seconds%3_600/60)} min`;
  return <div className="transport-line"><span>🚇</span><div className="departure-board"><div className="departure-heading"><span>{transport.status}</span>{next?.realtime&&<small className="realtime-badge">sanntid</small>}</div>{next&&countdown?<><strong className="departure-countdown" aria-live="off">{countdown}</strong><span className="departure-destination"><b>Linje {next.line}</b> til {next.destination} · spor {next.platform}</span><div className="following-departures" aria-label="Senere avganger">{upcoming.slice(1,4).map(item=><span key={item.expected_departure}><b>{timeFormat.format(asDate(item.expected_departure)!)}</b> {item.destination}</span>)}</div></>:<strong className="departure-unavailable">{transport.stale?"Ingen ferske avganger akkurat nå":"Ingen avganger funnet"}</strong>}<small>{transport.stop} · {transport.stale?"sist lagrede data":"oppdatert"} {when(transport.updated_at)}</small></div></div>
}

function WeeklyAchievement({achievement}:{achievement?:WeeklyAchievement}){
  if(!achievement)return null;
  const ready=achievement.ready_surprises||[];
  const fullTabs=achievement.full_tabs??achievement.full_weeks??0;
  return <section className="weekly-achievement"><div><p className="eyebrow">Samlet fremgang</p><h2>{fullTabs} fulle blokker</h2><p className="weekly-copy">{achievement.current_points} / {achievement.target_points} poeng mot neste blokk · {fullTabs} fullført</p></div><div className="weekly-progress" role="progressbar" aria-label={`${fullTabs} fulle blokker og ${achievement.current_points} poeng mot neste`} aria-valuemin={0} aria-valuemax={achievement.target_points} aria-valuenow={achievement.current_points}><i style={{width:`${achievement.current_percent}%`}}/></div>{ready.length?<div className="weekly-ready"><strong>Overraskelse klar 🎁</strong><span>{ready.map(item=>`${item.emoji} ${item.title}`).join(" · ")}</span></div>:achievement.next_surprise?<p className="weekly-next">Neste overraskelse ved {achievement.next_surprise.threshold_weeks} fulle blokker: {achievement.next_surprise.emoji} {achievement.next_surprise.title}</p>:<p className="weekly-next">Foreldrene kan legge inn en overraskelse i foreldremodus.</p>}</section>
}

function ChildPage({child,data,busy,complete,openWeekPlan}:{child:Child;data:Dashboard;busy:number|string|null;complete:(chore:Chore)=>Promise<void>;openWeekPlan:(childId:number,planId:number)=>void}){
  const achievement=child.weekly_achievement;
  const fullTabs=achievement?.full_tabs??achievement?.full_weeks??0;
  const blockTarget=achievement?.target_points??30;
  const blockPoints=achievement?.current_points??0;
  const blockPercent=achievement?.current_percent??0;
  const blockRemaining=Math.max(0,blockTarget-blockPoints);
  return <><section className="kid-hero"><div className="kid-name"><span>{child.avatar}</span><div><p className="eyebrow">Min side</p><h1>{child.name}</h1></div></div>{child.reward?<div className="reward-card"><div className="reward-top"><div><span>Aktiv 30-poengsblokk</span><h2>{child.reward.emoji} {child.reward.title}</h2></div><strong>{blockPercent}%</strong></div><div className="progress-track" role="progressbar" aria-label="Aktiv 30-poengsblokk" aria-valuemin={0} aria-valuemax={blockTarget} aria-valuenow={blockPoints}><i style={{width:`${blockPercent}%`}}/></div><div className="reward-copy"><strong>{blockPoints} / {blockTarget} poeng</strong><span>{blockRemaining?`${blockRemaining} poeng igjen → ${child.reward.title} 🎯`:`Ny blokk startet! ${fullTabs} fullført 🎉`}</span></div></div>:<div className="reward-card"><h2>🎯 Velg et mål sammen</h2></div>}</section><WeeklyAchievement achievement={achievement}/><WeekPlan data={data} child={child} openDetails={planId=>openWeekPlan(child.id,planId)}/>
  <section className="missions"><div className="section-heading"><div><p className="eyebrow">Mine oppdrag</p><h2>Hva vil du gjøre?</h2></div><span className="count-badge">{child.chores.length} igjen</span></div><div className="mission-grid">{child.chores.map(chore=>{const repeated=chore.repeat_mode==="weekly";const unavailable=repeated&&!chore.available_today;const pending=repeated&&chore.repeat_status==="pending";return <button key={chore.id} className="mission-card" disabled={busy!==null||unavailable||pending} onClick={()=>void complete(chore)}><span className="mission-icon">{chore.icon}</span><span className="mission-title"><strong>{chore.title}</strong><small>{repeated?(pending?"Venter på godkjenning":unavailable?"Ikke planlagt i dag":`${chore.repeat_completed}/${chore.repeat_target} denne uken`):chore.requires_approval?"En voksen godkjenner":"Trykk når du er ferdig"}</small>{repeated&&<span className="mission-progress" role="progressbar" aria-valuemin={0} aria-valuemax={chore.repeat_target} aria-valuenow={chore.repeat_completed}><i style={{width:`${chore.repeat_percent}%`}}/></span>}</span><span className="points">+{chore.points}<small>poeng</small></span><span className="done">{busy===chore.id?"Lagrer …":pending?"Til kontroll":unavailable?"Kommer senere":"Ferdig ✓"}</span></button>})}{child.chores.length===0&&<div className="all-done"><span>✨</span><h3>Klar for nye oppdrag!</h3><p>Lag de første oppdragene sammen i foreldresiden.</p></div>}</div></section>
  <section className="child-lower"><article className="history-card"><p className="eyebrow">Min historie</p><h2>Dette har jeg gjort</h2><div className="history-list">{child.history.map(item=><div key={item.id}><span>{item.icon||"✨"}</span><div><strong>{item.title}</strong><small>{when(item.completed_at)}</small></div><b className={item.status}>{item.status==="rejected"?"Prøv igjen":`+${item.points}`}</b></div>)}{!child.history.length&&<p className="empty-text">De første fullførte oppdragene vises her.</p>}</div></article><Glance data={data} child={child}/></section></>
}

function ParentPage({data,unlocked,busy,unlock,addChore,decide,archive,reward,saveWeeklySurprise,deleteWeeklySurprise,resetWeeklyAchievement,resetChild}:{data:Dashboard;unlocked:boolean;busy:number|string|null;unlock:(event:FormEvent<HTMLFormElement>)=>Promise<void>;addChore:(event:FormEvent<HTMLFormElement>)=>Promise<void>;decide:(id:number,decision:"awarded"|"rejected")=>Promise<void>;archive:(id:number)=>Promise<void>;reward:(event:FormEvent<HTMLFormElement>)=>Promise<void>;saveWeeklySurprise:(event:FormEvent<HTMLFormElement>)=>Promise<void>;deleteWeeklySurprise:(memberId:number,threshold:number)=>Promise<void>;resetWeeklyAchievement:(memberId:number,threshold?:number)=>Promise<void>;resetChild:(memberId:number,scope:"chores"|"points"|"both")=>Promise<void>}){
  const [resetMemberId,setResetMemberId]=useState(data.children[0]?.id||0);
  const [weeklyMemberId,setWeeklyMemberId]=useState(data.children[0]?.id||0);
  const weeklyChild=data.children.find(item=>item.id===weeklyMemberId);
  const weekdayNames=[[1,"Man"],[2,"Tir"],[3,"Ons"],[4,"Tor"],[5,"Fre"],[6,"Lør"],[7,"Søn"]] as const;
  return <section className="parent-shell"><div className="parent-heading"><div><p className="eyebrow">Foreldremodus</p><h1>Oppsett og godkjenning</h1></div><span>🔐 Kun voksne</span></div>{!unlocked?<form className="pin-form" onSubmit={unlock}><label>Foreldrekode<input name="pin" type="password" inputMode="numeric" pattern="[0-9]*" required/></label><button disabled={busy==="pin"}>Lås opp</button></form>:<div className="parent-grid">
    <form className="parent-card" onSubmit={addChore}><p className="eyebrow">Nytt oppdrag</p><h2>Legg til gjøremål</h2><label>Hva skal gjøres?<input name="title" required maxLength={160} placeholder="Pakke gymtøy"/></label><div className="form-row"><label>Barn<select name="assigned_to">{data.children.map(item=><option key={item.id} value={item.name.toLowerCase()}>{item.name}</option>)}</select></label><label>Poeng<input name="points" type="number" min="0" max="1000" defaultValue="5" required/></label></div><fieldset><legend>Ikon</legend><div className="icon-picker">{icons.map((icon,index)=><label key={icon}><input type="radio" name="icon" value={icon} defaultChecked={index===0}/><span>{icon}</span></label>)}</div></fieldset><label className="check"><input name="requires_approval" type="checkbox"/><span>Krever godkjenning</span></label><label className="check"><input name="repeat_mode" value="weekly" type="checkbox"/><span>Gjenta hver uke</span></label><fieldset className="repeat-settings"><legend>Ukedager for gjentakelsen</legend><div className="weekday-picker">{weekdayNames.map(([value,label])=><label key={value}><input name="repeat_weekdays" value={value} type="checkbox" defaultChecked={value<=5}/><span>{label}</span></label>)}</div><small>Oppdraget gir poeng eller går til kontroll etter alle valgte dager.</small></fieldset><button className="primary" disabled={busy==="add"}>Legg til oppdrag</button></form>
    <article className="parent-card"><p className="eyebrow">Voksenkontroll</p><h2>Nylig registrert</h2><p className="parent-help">Barna får progresjon med en gang. Underkjenn hvis oppgaven ikke faktisk er gjort; da trekkes poengene og oppgaven åpnes igjen.</p><div className="approval-list">{data.review_queue.map(item=><div key={item.id}><div><strong>{item.icon} {item.title}</strong><span>{item.member} · {item.cycle_points||item.points} poeng · {item.cycle_required?`${item.cycle_completed}/${item.cycle_required} repetisjoner · `:""}{item.status==="pending"?"bør kontrolleres":"registrert"}</span></div><div>{item.status==="pending"&&<button onClick={()=>void decide(item.id,"awarded")}>Godkjenn</button>}<button className="quiet reject" onClick={()=>void decide(item.id,"rejected")}>Underkjenn</button></div></div>)}{!data.review_queue.length&&<p className="empty-text">Ingen fullføringer er registrert ennå.</p>}</div></article>
    <form className="parent-card" onSubmit={reward}><p className="eyebrow">Belønning</p><h2>Sett nytt mål</h2><label>Barn<select name="member_id">{data.children.map(item=><option key={item.id} value={item.id}>{item.name}</option>)}</select></label><div className="form-row reward-input"><label>Emoji<input name="emoji" defaultValue="🎯" maxLength={12}/></label><label>Belønning<input name="title" required placeholder="Kinokveld"/></label></div><label>Poengmål<input name="target_value" type="number" min="1" defaultValue="30" required/></label><button className="primary">Start nytt mål</button></form>
    <WeeklyParentCard data={data} weeklyMemberId={weeklyMemberId} setWeeklyMemberId={setWeeklyMemberId} weeklyChild={weeklyChild} busy={busy} saveWeeklySurprise={saveWeeklySurprise} deleteWeeklySurprise={deleteWeeklySurprise} resetWeeklyAchievement={resetWeeklyAchievement}/><article className="parent-card"><p className="eyebrow">Ny rutine</p><h2>Nullstill for et barn</h2><p className="parent-help">Historikken beholdes. Aktiv oppgaveliste og poeng kan startes på nytt separat.</p><label>Barn<select value={resetMemberId} onChange={event=>setResetMemberId(Number(event.target.value))}>{data.children.map(item=><option key={item.id} value={item.id}>{item.name}</option>)}</select></label><div className="reset-actions"><button type="button" onClick={()=>void resetChild(resetMemberId,"chores")} disabled={busy!==null}>Nullstill oppgaver</button><button type="button" onClick={()=>void resetChild(resetMemberId,"points")} disabled={busy!==null}>Nullstill poeng</button><button type="button" className="primary" onClick={()=>void resetChild(resetMemberId,"both")} disabled={busy!==null}>Nullstill begge</button></div></article>
    <article className="parent-card"><p className="eyebrow">Aktive oppdrag</p><h2>Administrer</h2><div className="manage-list">{data.children.flatMap(child=>child.chores.map(chore=><div key={chore.id}><span>{chore.icon}</span><div><strong>{chore.title}</strong><small>{child.name} · {chore.points} poeng{chore.repeat_mode==="weekly"?` · ${chore.repeat_target} ganger per uke`:""}</small></div><button onClick={()=>void archive(chore.id)}>Fjern</button></div>))}</div></article>
  </div>}</section>
}

const kanbanColumns:[{lane:KanbanLane;label:string},{lane:KanbanLane;label:string},{lane:KanbanLane;label:string},{lane:KanbanLane;label:string}]=[
  {lane:"todo",label:"New"},
  {lane:"inprogress",label:"In Progress"},
  {lane:"onhold",label:"Pause"},
  {lane:"done",label:"Done"},
];

function KanbanPage({data,unlocked,busy,unlock,addKanban,moveKanban,archiveKanban}:{data:Dashboard;unlocked:boolean;busy:number|string|null;unlock:(event:FormEvent<HTMLFormElement>)=>Promise<void>;addKanban:(event:FormEvent<HTMLFormElement>)=>Promise<void>;moveKanban:(id:number,lane:KanbanLane)=>Promise<void>;archiveKanban:(id:number)=>Promise<void>}){
  const cards=data.chores||[];
  if(!unlocked)return <section className="kanban-shell"><div className="kanban-heading"><div><p className="eyebrow">Foreldresider</p><h1>Kanban</h1><p>Dette er familiens oppgavetavle, separat fra barnas poengoppdrag.</p></div></div><article className="kanban-lock parent-card"><p className="eyebrow">Foreldrekontroll</p><h2>Kanban er skrivebeskyttet</h2><p className="parent-help">Lås opp med foreldrekoden for å opprette, flytte eller fjerne oppgaver.</p><form className="pin-form" onSubmit={unlock}><label>Foreldrekode<input name="pin" type="password" inputMode="numeric" pattern="[0-9]*" required/></label><button disabled={busy==="pin"}>Lås opp</button></form></article></section>;
  return <section className="kanban-shell"><div className="kanban-heading"><div><p className="eyebrow">Familiens oppgaver</p><h1>Kanban</h1><p>Flytt oppgaver mellom kolonnene. Ferdige oppgaver beholdes med de nyeste øverst.</p></div><span>🗂️ {cards.length} oppgaver</span></div>{unlocked?<form className="kanban-new parent-card" onSubmit={addKanban}><div><p className="eyebrow">Ny oppgave</p><h2>Legg til i Kanban</h2></div><div className="kanban-form-grid"><label>Hva skal gjøres?<input name="title" required maxLength={160} placeholder="Bestille billetter"/></label><label>Hvem gjelder det?<select name="assigned_to"><option value="both">Familien</option>{data.children.map(item=><option key={item.id} value={item.name.toLowerCase()}>{item.name}</option>)}</select></label><label>Prioritet<select name="priority" defaultValue="nice-to"><option value="must-do">Viktigst</option><option value="important">Viktig</option><option value="nice-to">Vanlig</option></select></label><label>Frist<input name="due_date" type="date"/></label></div><label>Beskrivelse<textarea name="description" rows={2} maxLength={1000} placeholder="Valgfritt"/></label><button className="primary" disabled={busy==="kanban-add"}>Legg til oppgave</button></form>:<article className="kanban-lock parent-card"><p className="eyebrow">Foreldrekontroll</p><h2>Kanban er skrivebeskyttet</h2><p className="parent-help">Lås opp med foreldrekoden for å opprette, flytte eller fjerne oppgaver.</p><form className="pin-form" onSubmit={unlock}><label>Foreldrekode<input name="pin" type="password" inputMode="numeric" pattern="[0-9]*" required/></label><button disabled={busy==="pin"}>Lås opp</button></form></article>}<div className="kanban-grid">{kanbanColumns.map(column=>{const laneCards=cards.filter(card=>card.lane===column.lane).sort((left,right)=>right.updated_at.localeCompare(left.updated_at)||right.id-left.id);return <section className={`kanban-column lane-${column.lane}`} key={column.lane}><header><div><p className="eyebrow">Status</p><h2>{column.label}</h2></div><span>{laneCards.length}</span></header><div className="kanban-card-list">{laneCards.map(card=><article className="kanban-card" key={card.id}><div className="kanban-card-copy"><strong>{card.title}</strong>{card.description&&<p>{card.description}</p>}<small>{card.assigned_to==="both"?"Familien":card.assigned_to}{card.due_date?` · frist ${card.due_date}`:""}</small></div>{unlocked&&<div className="kanban-card-actions"><select aria-label={`Flytt ${card.title}`} value={card.lane} onChange={event=>void moveKanban(card.id,event.target.value as KanbanLane)} disabled={busy===`kanban-move-${card.id}`}><option value="todo">New</option><option value="inprogress">In Progress</option><option value="onhold">Pause</option><option value="done">Done</option></select><button type="button" className="kanban-delete" onClick={()=>void archiveKanban(card.id)} disabled={busy===`kanban-delete-${card.id}`}>Slett</button></div>}</article>)}{laneCards.length===0&&<p className="kanban-empty">Ingen oppgaver her.</p>}</div></section>})}</div></section>
}

function WeeklyParentCard({data,weeklyMemberId,setWeeklyMemberId,weeklyChild,busy,saveWeeklySurprise,deleteWeeklySurprise,resetWeeklyAchievement}:{data:Dashboard;weeklyMemberId:number;setWeeklyMemberId:(value:number)=>void;weeklyChild:Child|undefined;busy:number|string|null;saveWeeklySurprise:(event:FormEvent<HTMLFormElement>)=>Promise<void>;deleteWeeklySurprise:(memberId:number,threshold:number)=>Promise<void>;resetWeeklyAchievement:(memberId:number,threshold?:number)=>Promise<void>}){
  const achievement=weeklyChild?.weekly_achievement;
  const ready=achievement?.ready_surprises||[];
  if(!achievement)return null;
  const fullTabs=achievement.full_tabs??achievement.full_weeks??0;
  return <article className="parent-card weekly-parent-card"><p className="eyebrow">Samlet fremgang</p><h2>Fulle 30-poengsblokker</h2><p className="parent-help">Hver blokk fylles med 30 poeng. Når den er full, starter neste blokk med en gang, og telleren fortsetter til barnet tar ut en overraskelse.</p><label>Barn<select value={weeklyMemberId} onChange={event=>setWeeklyMemberId(Number(event.target.value))}>{data.children.map(item=><option key={item.id} value={item.id}>{item.name}</option>)}</select></label><div className="weekly-parent-summary"><strong>{fullTabs} fulle blokker</strong><span>{achievement.current_points} / {achievement.target_points} poeng mot neste blokk</span></div><form className="weekly-surprise-form" onSubmit={saveWeeklySurprise}><input type="hidden" name="member_id" value={weeklyMemberId}/><label>Ved antall fulle blokker<input name="threshold_weeks" type="number" min="1" max="10000" defaultValue={achievement.next_surprise?.threshold_weeks||4} required/></label><label>Emoji<input name="emoji" defaultValue="🎁" maxLength={12}/></label><label>Overraskelse<input name="title" placeholder="Velg noe hyggelig" required maxLength={80}/></label><button className="primary" disabled={busy==="weekly-surprise"}>Lagre nivå</button></form><div className="surprise-list">{achievement.surprises.map(item=><div key={item.id}><span>{item.emoji}</span><div><strong>{item.threshold_weeks} blokker · {item.title}</strong><small>{fullTabs>=item.threshold_weeks?"Klar til uttak":"Neste nivå"}</small></div><button type="button" onClick={()=>void deleteWeeklySurprise(weeklyMemberId,item.threshold_weeks)} disabled={busy!==null}>Fjern</button></div>)}{ready.length>0&&<button type="button" className="primary weekly-reset-button" onClick={()=>void resetWeeklyAchievement(weeklyMemberId,ready[ready.length-1].threshold_weeks)} disabled={busy!==null}>Overraskelse tatt ut – nullstill teller</button>}</div></article>;
}

function Glance({data,child}:{data:Dashboard;child:Child}){const today=eventsFor(data,child);const activities=data.activities.filter(item=>item.member_id===child.id);return <article className="glance-card"><p className="eyebrow">Min dag</p><h2>Skole og aktivitet</h2>{today.map(item=><div className="glance-item" key={`${item.id}-${item.title}`}><strong>{eventTime(item)} · {item.title}</strong><small>{item.location||"I dag"}</small></div>)}{!today.length&&<p className="empty-text">Ingen særskilte avtaler i dag.</p>}{activities.slice(0,3).map(item=><div className="glance-item" key={item.id}><strong>{item.name}</strong><small>{item.schedule||"Tid kommer"}</small></div>)}</article>}
function WeekPlan({data,child,openDetails}:{data:Dashboard;child:Child;openDetails:(planId:number)=>void}){const plan=data.week_plans.find(item=>item.member_id===child.id);return <section className="week-plan"><div className="section-heading"><div><p className="eyebrow">Skolen denne uken</p><h2>Ukeplan</h2></div>{plan&&<div className="week-plan-heading-actions"><span className="week-badge">Uke {plan.week_number}{plan.fallback?" · forrige uke":""}</span><button type="button" className="week-plan-open" onClick={()=>openDetails(plan.id)}>Se hele ukeplanen →</button></div>}</div>{!plan&&<div className="no-week-plan"><span>📭</span><div><strong>Ingen ukeplan er registrert ennå</strong><p>Når skolen sender og FamilyBot har behandlet planen, kommer den hit - separat fra poengoppdragene.</p></div></div>}</section>}

function WeekPlanDetailPage({child,planId,token,onBack}:{child:Child;planId:number;token:string;onBack:()=>void}){
  const [detail,setDetail]=useState<WeekPlanDetail|null>(null);const [error,setError]=useState("");
  useEffect(()=>{let cancelled=false;void fetch(`${apiBase()}/api/children/${child.id}/week-plans/${planId}`,{headers:{"X-FamilyBot-Local-Token":token},cache:"no-store"}).then(async response=>{const result=await response.json();if(!response.ok)throw new Error(result.error||"Ukeplanen kunne ikke leses.");if(!cancelled)setDetail(result.week_plan)}).catch(cause=>{if(!cancelled)setError(cause instanceof Error?cause.message:"Ukeplanen kunne ikke leses.")});return()=>{cancelled=true}},[child.id,planId,token]);
  if(error)return <section className="week-plan-detail"><button type="button" className="back-button" onClick={onBack}>← Tilbake</button><p className="error-text">{error}</p></section>;
  if(!detail)return <section className="week-plan-detail"><button type="button" className="back-button" onClick={onBack}>← Tilbake</button><div className="loading-inline"><div className="spinner"/><p>Ukeplanen åpnes …</p></div></section>;
  return <section className="week-plan-detail"><button type="button" className="back-button" onClick={onBack}>← Tilbake til {child.name}</button><header><p className="eyebrow">Skolen denne uken</p><h1>Ukeplan · uke {detail.week_number}</h1><p className="week-detail-child">{detail.member}</p></header><p className="week-detail-summary">{detail.summary}</p><article className="week-detail-text"><h2>{detail.interpretation?"Ukeplanen strukturert":"Hele ukeplanen"}</h2>{detail.interpretation?renderWeekPlanInterpretation(detail.interpretation):renderWeekPlanText(detail.full_text)}</article>{detail.days.length>0&&<section className="week-detail-days"><h2>Dagene</h2><div className="week-items">{detail.days.map(item=><article key={item.id}><div><span>{item.day}</span>{item.date&&<time>{dateFormat.format(asDate(item.date)!)}</time>}</div>{item.subject&&<h3>{item.subject}</h3>}{item.homework&&<p><b>📚 Oppgave:</b> {item.homework}</p>}{item.note&&<p><b>ℹ️ Dette skjer:</b> {item.note}</p>}{item.bring&&<p><b>🎒 Husk:</b> {item.bring}</p>}</article>)}</div></section>}</section>
}
function eventLabel(item:EventItem,today:string){if(item.event_date.slice(0,10)===today)return eventTime(item);const parsed=asDate(item.event_date);const day=parsed?dateFormat.format(parsed):item.event_date.slice(0,10);const time=item.event_time?item.event_time.slice(0,5):parsed&&item.event_date.includes("T")?timeFormat.format(parsed):"";return time?`${day} · ${time}`:day}
function upcomingEventsFor(data:Dashboard){const seen=new Set<string>();const endDate=new Date(`${data.date}T12:00:00`);endDate.setDate(endDate.getDate()+4);const end=endDate.toISOString().slice(0,10);return [...data.events,...data.spond_events].filter(item=>{const date=item.event_date.slice(0,10);const key=`${item.title}|${date}|${item.member_id}`;if(date<data.date||date>end||seen.has(key))return false;seen.add(key);return true}).sort((left,right)=>left.event_date.localeCompare(right.event_date)||String(left.event_time||"").localeCompare(String(right.event_time||""))||left.title.localeCompare(right.title)).slice(0,4)}
function eventsFor(data:Dashboard,child?:Child){const seen=new Set<string>();return [...data.events,...data.spond_events].filter(item=>{const key=`${item.title}|${item.event_date}|${item.member_id}`;if(item.event_date.slice(0,10)!==data.date||seen.has(key)||child&&(item.member_id!==null&&item.member_id!==undefined&&item.member_id!==child.id))return false;seen.add(key);return true}).slice(0,6)}
